#!/usr/bin/env python3
"""type-only-imports.py <folder>: ONE CASE A FOLDER: which modules an unused or type-only import evaluates: `import type`, an import of which only types are used, `export type`, re-exports of types, beside a module that has a value too."""
import os, sys

CASES = {'t1': {'lib.ts': 'import type { T } from "./types"; export const x: T = { a: 1 };\n', 'main.ts': 'import { x } from "./lib"; console.log(x.a);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't2': {'lib.ts': 'import { T } from "./types"; export const x: T = { a: 1 }; export default 5;\n', 'main.ts': 'import d, { x } from "./lib"; console.log(x.a, d);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't3': {'lib.ts': 'import { type T, type I } from "./types"; export function f(t: T, i: I): string { return t.a + i.b; }\n', 'main.ts': 'import { f } from "./lib"; console.log(f({ a: 1 }, { b: "b" }));\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't4': {'lib.ts': 'import type { T } from "./types"; export default class K { t: T = { a: 2 }; }\n', 'main.ts': 'import K from "./lib"; console.log(new K().t.a);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't5': {'lib.ts': 'import type { T } from "./types"; export type { T }; export * from "./types";\n', 'main.ts': 'import { real } from "./lib"; console.log(real);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't6': {'lib.ts': 'import { T } from "./types"; const x: T = { a: 1 }; exports.x = x;\n', 'main.ts': 'const { x } = require("./lib"); console.log(x.a);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't7': {'lib.ts': 'import { T } from "./types"; const x: T = { a: 1 }; export { x as y };\n', 'main.ts': 'import * as l from "./lib"; console.log(l.y.a, Object.keys(l).join());\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't8': {'lib.ts': 'import { T } from "./types"; let n = 0; export const bump = (t: T): number => n += t.a; export { n };\n', 'main.ts': 'import { bump, n } from "./lib"; bump({ a: 2 }); console.log(n);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't9': {'lib.ts': 'import { T } from "./types"; const top = await Promise.resolve<T>({ a: 3 }); export const v = top.a;\n', 'main.ts': 'import { v } from "./lib"; console.log(v);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't10': {'lib.ts': 'import { T } from "./types"; export const where = typeof module + ":" + typeof exports + ":" + typeof require + ":" + typeof import.meta.url + ":" + (function (this: unknown) { return typeof this; })();\n', 'main.ts': 'import { where } from "./lib"; console.log(where);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't11': {'lib.ts': 'import { T } from "./types"; console.log("lib runs", typeof module, this === undefined); const x: T = { a: 1 }; export {};\n', 'main.ts': 'import "./lib"; console.log("main");\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't12': {'lib.ts': 'export {}; declare global { var shared: number } globalThis.shared = 4;\n', 'main.ts': 'import "./lib"; console.log(shared);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't13': {'lib.ts': 'import { T } from "./types"; namespace N { export const v = 1; } export import V = N.v; export const t: T = { a: V };\n', 'main.ts': 'import { V, t } from "./lib"; console.log(V, t.a);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}, 't14': {'lib.ts': 'import { T } from "./types"; export = { a: 1 } as T;\n', 'main.ts': 'import x = require("./lib"); console.log(x.a);\n', 'types.ts': 'export type T = { a: number }; export interface I { b: string } export const real = 9;\n'}}

for case, files in CASES.items():
    for name, text in files.items():
        path = os.path.join(sys.argv[1], case, name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, "w").write(text)
